def sha_file(p): return sha_bytes(Path(p).read_bytes())
def load(name,path):
 spec=importlib.util.spec_from_file_location('fault_'+name,path); mod=importlib.util.module_from_spec(spec); spec.loader.exec_module(mod); return mod

def call(mod,args):
